/* ============================================
   POPOVER COMPONENT
   Contextual overlay panel
   ============================================ */

.ds-popover {
  position: relative;
  display: inline-flex;
}

/* ============================================
   TRIGGER
   ============================================ */

.ds-popover__trigger {
  display: inline-flex;
  cursor: pointer;
}

/* ============================================
   PANEL
   ============================================ */

.ds-popover__panel {
  position: absolute;
  z-index: 10;
  min-width: 200px;
  padding: var(--padding-400); /* 16px */
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-200); /* 8px */
  /* Page background, not container: the container fill is semi-transparent
     in dark mode, and a floating panel must not show text through itself */
  background-color: var(--color-bg-page-primary);
  box-shadow: var(--shadow-floating);

  /* Hidden by default. display:none keeps the closed panel out of the tab
     order and accessibility tree AND out of the page's scrollable overflow —
     a min-width 200px panel on an edge-adjacent trigger would otherwise add
     horizontal scroll while invisible (see Tooltip, where the leak was
     found). allow-discrete holds the panel through the exit fade,
     @starting-style below supplies the entry frame; browsers without those
     skip the fades but open and close correctly. */
  display: none;
  opacity: 0;
  pointer-events: none;
  transform: scale(0.96);
  transition-property: opacity, transform, display;
  transition-duration: var(--motion-duration-base);
  transition-timing-function: var(--motion-ease-standard);
  transition-behavior: allow-discrete;
}

.ds-popover__panel--open {
  display: block;
  opacity: 1;
  pointer-events: auto;
  transform: scale(1);
}

/* Entry state for the display flip: a panel arriving from display:none has
   no prior computed style, so this supplies the fade's starting frame. */
@starting-style {
  .ds-popover__panel--open {
    opacity: 0;
    transform: scale(0.96);
  }
}

/* ============================================
   POSITION — BOTTOM (default)
   ============================================ */

.ds-popover__panel--bottom {
  top: 100%;
  left: 0;
  margin-top: var(--gap-050); /* 2px */
}

/* ============================================
   POSITION — TOP
   ============================================ */

.ds-popover__panel--top {
  bottom: 100%;
  left: 0;
  margin-bottom: var(--gap-050); /* 2px */
}

/* ============================================
   POSITION — LEFT
   ============================================ */

.ds-popover__panel--left {
  right: 100%;
  top: 0;
  margin-right: var(--gap-050); /* 2px */
}

/* ============================================
   POSITION — RIGHT
   ============================================ */

.ds-popover__panel--right {
  left: 100%;
  top: 0;
  margin-left: var(--gap-050); /* 2px */
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

/* The size class rides on the panel element itself, so this is a plain
   compound selector — a descendant form would never match */
.ds-popover--compact {
  padding: var(--padding-200); /* 8px */
  min-width: 160px;
}

'use client';

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { MOTION_HOVER_HIDE_DELAY_MS } from '../../tokens/motion';
import './Popover.css';

export interface PopoverProps {
  /** Trigger element */
  children: React.ReactNode;
  /** Popover content */
  content: React.ReactNode;
  /** Component size */
  size?: 'default' | 'compact';
  /** Preferred position */
  position?: 'top' | 'bottom' | 'left' | 'right';
  /** Trigger mode */
  trigger?: 'click' | 'hover';
  /** Whether the popover is open (controlled mode) */
  open?: boolean;
  /** Callback when open state changes */
  onOpenChange?: (open: boolean) => void;
  /** Accessible label for the trigger */
  ariaLabel?: string;
  /** Additional CSS classes for the popover panel */
  className?: string;
}

/**
 * Popover component for contextual overlays.
 * Wraps a trigger element and displays content in a
 * positioned panel. Supports click and hover triggers
 * with automatic outside-click dismissal.
 */
/**
 * Whether an element may legally carry aria-expanded / aria-haspopup.
 * Intrinsic tags are checked against the interactive set; a custom component
 * is assumed to render a real control (every component in this library
 * spreads unrecognised props onto its primary node).
 */
const INTERACTIVE_TAGS = new Set(['button', 'a', 'input', 'select', 'textarea', 'summary']);
const canCarryPopoverSemantics = (el: React.ReactElement): boolean =>
  typeof el.type === 'string' ? INTERACTIVE_TAGS.has(el.type) : true;

export const Popover = ({
  children,
  content,
  size = 'default',
  position = 'bottom',
  trigger = 'click',
  open: controlledOpen,
  onOpenChange,
  ariaLabel,
  className = '',
}: PopoverProps) => {
  const [internalOpen, setInternalOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const hoverTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);

  const isControlled = controlledOpen !== undefined;
  const isOpen = isControlled ? controlledOpen : internalOpen;

  const setOpen = useCallback((next: boolean) => {
    if (!isControlled) {
      setInternalOpen(next);
    }
    onOpenChange?.(next);
  }, [isControlled, onOpenChange]);

  useEffect(() => {
    return () => clearTimeout(hoverTimeoutRef.current);
  }, []);

  // Click outside to close
  useEffect(() => {
    if (!isOpen || trigger !== 'click') return;

    const handler = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };

    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [isOpen, trigger, setOpen]);

  // Escape key to close
  useEffect(() => {
    if (!isOpen) return;

    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setOpen(false);
      }
    };

    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [isOpen, setOpen]);

  const handleClick = () => {
    if (trigger === 'click') {
      setOpen(!isOpen);
    }
  };

  const handleMouseEnter = () => {
    if (trigger === 'hover') {
      clearTimeout(hoverTimeoutRef.current);
      setOpen(true);
    }
  };

  const handleMouseLeave = () => {
    if (trigger === 'hover') {
      hoverTimeoutRef.current = setTimeout(() => setOpen(false), MOTION_HOVER_HIDE_DELAY_MS);
    }
  };

  const baseClass = 'ds-popover';
  const sizeClass = `${baseClass}--${size}`;
  const positionClass = `${baseClass}__panel--${position}`;
  const openClass = isOpen ? `${baseClass}__panel--open` : '';

  const containerClasses = [baseClass, className].filter(Boolean).join(' ');
  const panelClasses = [`${baseClass}__panel`, sizeClass, positionClass, openClass]
    .filter(Boolean)
    .join(' ');

  return (
    <div
      className={containerClasses}
      ref={containerRef}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      {/*
        The trigger content is consumer-supplied and is normally already a
        control. Putting role="button" on the wrapper nested one interactive
        element inside another — instead, clone the popover semantics onto the
        real control, and only synthesise a button when there is nothing to
        clone onto.
      */}
      <div className={`${baseClass}__trigger`} onClick={handleClick}>
        {React.isValidElement(children) && canCarryPopoverSemantics(children) ? (
          React.cloneElement(children as React.ReactElement<Record<string, unknown>>, {
            'aria-expanded': isOpen,
            'aria-haspopup': 'dialog',
            ...(ariaLabel ? { 'aria-label': ariaLabel } : {}),
          })
        ) : trigger === 'click' ? (
          <button
            type="button"
            aria-expanded={isOpen}
            aria-haspopup="dialog"
            aria-label={ariaLabel}
          >
            {children}
          </button>
        ) : (
          children
        )}
      </div>

      <div
        className={panelClasses}
        role="dialog"
        // role="dialog" requires an accessible name.
        aria-label={ariaLabel || 'Popover'}
        aria-hidden={!isOpen}
      >
        {content}
      </div>
    </div>
  );
};
